//! 🧪️ Original typed wire source pointer, exact allocator receipts, scalar body minima and paid full closure.
use super::*;
use crate::{ArtifactCanonicalJsonNode as Node,ArtifactCanonicalJsonText as Text};
use semio_framework_trace::observe_heap_allocations_on_this_thread;
#[derive(serde::Serialize,semio_framework_value::RetireOwned)]
struct Original{id:u64,name:String,values:Vec<u64>}
impl Tree for Original{
 fn canonical_tree_node(&self)->Result<Node<'_>,ValueError>{Ok(Node::Object(3))}
 fn canonical_tree_key(&self,ordinal:usize)->Result<Text<'_>,ValueError>{match ordinal{0=>Ok("id".into()),1=>Ok("name".into()),2=>Ok("values".into()),_=>Err(refuses("original wire fixture key is absent"))}}
 fn canonical_tree_child(&self,ordinal:usize)->Result<&dyn Tree,ValueError>{match ordinal{0=>Ok(&self.id),1=>Ok(&self.name),2=>Ok(&self.values),_=>Err(refuses("original wire fixture child is absent"))}}
}
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
struct Stock{remaining:RetainedCloneGrant,work:u64,capacity:usize,released:usize,initial:RetainedCloneGrant}
impl Stock{
 fn new()->Self{let initial=RetainedCloneGrant{maximum_items:1000000,maximum_copy_bytes:10000000,maximum_capacity_bytes:10000000,maximum_release_bytes:10000000,maximum_depth:128};Self{remaining:initial,work:0,capacity:0,released:0,initial}}
 fn grant(&self,body:usize)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:self.remaining.maximum_items.min(1),maximum_copy_bytes:self.remaining.maximum_copy_bytes.min(body),maximum_capacity_bytes:self.remaining.maximum_capacity_bytes,maximum_release_bytes:self.remaining.maximum_release_bytes,maximum_depth:self.remaining.maximum_depth}}
 fn receive(&mut self,receipt:RetainedCloneProgress,heap:(usize,usize)){assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));assert!(receipt.fits(self.remaining));self.work+=receipt.copied_items as u64;self.capacity+=heap.0;self.released+=heap.1;self.remaining.maximum_items-=receipt.copied_items;self.remaining.maximum_copy_bytes-=receipt.copied_bytes;self.remaining.maximum_capacity_bytes-=receipt.retained_capacity_bytes;self.remaining.maximum_release_bytes-=receipt.released_bytes;assert_eq!(self.remaining.maximum_items+self.work as usize,self.initial.maximum_items);assert_eq!(self.remaining.maximum_capacity_bytes+self.capacity,self.initial.maximum_capacity_bytes);assert_eq!(self.remaining.maximum_release_bytes+self.released,self.initial.maximum_release_bytes)}
}
fn denied<T:Tree+RetireOwned>(cursor:&mut ArtifactCanonicalJsonTreeWireCursor<T>,stock:&Stock){let grant=stock.grant(64);let demand=cursor.next_demand(grant.maximum_copy_bytes).unwrap();for grant in [Some(RetainedCloneGrant{maximum_items:0,..grant}),Some(RetainedCloneGrant{maximum_depth:demand.depth.saturating_sub(1),..grant}),(demand.capacity_bytes>0).then_some(RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes.saturating_sub(1),..grant}),(demand.release_bytes>0).then_some(RetainedCloneGrant{maximum_release_bytes:demand.release_bytes.saturating_sub(1),..grant}),(!matches!(cursor.phase(),"sourceClose")&&demand.copy_bytes>0).then_some(RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes.saturating_sub(1),..grant})].into_iter().flatten(){let(result,heap)=observe(||cursor.advance(grant));let step=result.unwrap();assert!(step.output.is_none());assert_eq!(step.progress,Default::default());assert_eq!(heap,(0,0));assert_eq!(cursor.next_demand(64).unwrap(),demand)}}
#[test]
fn original_tree_wire_source_same_pointer_two_pass_system_denial_and_full_close(){
 let law:serde_json::Value=serde_json::from_str(crate::text("🛫️encode/🧭️tree/📨️wire/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let(original,factory)=observe(||Original{id:17,name:"source 源 é".into(),values:vec![1,2,3]});let pointers=(original.name.as_ptr(),original.values.as_ptr());let expected=serde_json::to_vec(&original).unwrap();assert_eq!(std::str::from_utf8(&expected).unwrap(),law["output"].as_str().unwrap());let(mut cursor,system)=observe(||ArtifactCanonicalJsonTreeWireCursor::new(original));assert_eq!(system,(0,0));let mut stock=Stock::new();stock.receive(RetainedCloneProgress{retained_capacity_bytes:factory.0,released_bytes:factory.1,..Default::default()},factory);let mut returned=None;let mut seen_scalar=false;let mut allocated_wire=None;
 for turn in 0..100000{if let Some(root)=cursor.original(){assert_eq!(root.name.as_ptr(),pointers.0);assert_eq!(root.values.as_ptr(),pointers.1)}let demand=cursor.next_demand(64).unwrap();if demand.copy_bytes==64{seen_scalar=true}denied(&mut cursor,&stock);let grant=stock.grant(64);let(step,heap)=observe(||cursor.advance(grant).unwrap());assert!(step.progress.fits(grant));if cursor.phase()=="initialize"{let pointer=cursor.wire.as_ptr();if let Some(original)=allocated_wire{assert_eq!(pointer,original)}else{allocated_wire=Some(pointer)}}stock.receive(step.progress,heap);if let Some(output)=step.output{returned=Some(output);break}assert!(turn<99999,"original typed wire stalled phase={} demand={demand:?}",cursor.phase())}
 let output=returned.unwrap();assert!(seen_scalar);assert_eq!(output,expected);assert_eq!(output.as_ptr(),allocated_wire.unwrap());assert!(cursor.terminal_is_empty());assert_eq!(cursor.measured_byte_length(),output.len());assert_eq!(cursor.output_bytes_written(),output.len());assert_eq!(observe(||drop(cursor)).1,(0,0));let output_capacity=output.capacity();let(mut close,heap)=observe(||ControlledRetirement::new(output).unwrap_or_else(|_|panic!("original wire output has typed retirement")));assert_eq!(heap,(0,0));for turn in 0..100000{if close.terminal_is_empty(){break}let grant=stock.grant(3);let(step,heap)=observe(||close.step(grant).unwrap());stock.receive(step.progress(),heap);assert!(turn<99999,"original wire output close stalled")}
 assert_eq!(stock.capacity,stock.released);assert!(output_capacity>0);assert_eq!(observe(||drop(close)).1,(0,0));
}
#[test]
fn original_tree_wire_cancel_retains_every_partial_typed_source_and_destination(){
 for phase in ["measure","allocate","initialize","encode","sourceClose","handoff"]{for body in [0,1,3,64]{let(original,factory)=observe(||Original{id:17,name:"original source 源 é".repeat(100),values:vec![1,2,3]});let pointer=original.name.as_ptr();let mut cursor=ArtifactCanonicalJsonTreeWireCursor::new(original);let mut stock=Stock::new();stock.receive(RetainedCloneProgress{retained_capacity_bytes:factory.0,released_bytes:factory.1,..Default::default()},factory);for turn in 0..100000{if cursor.phase()==phase{break}if let Some(root)=cursor.original(){assert_eq!(root.name.as_ptr(),pointer)}let grant=stock.grant(64);let(step,heap)=observe(||cursor.advance(grant).unwrap());assert!(step.output.is_none());stock.receive(step.progress,heap);assert!(turn<99999,"original cancellation phase not reached {phase}")}
 let(_,heap)=observe(||cursor.begin_close());assert_eq!(heap,(0,0));for turn in 0..100000{if cursor.terminal_is_empty(){break}let demand=cursor.next_demand(body).unwrap();let grant=stock.grant(body);let(receipt,heap)=observe(||cursor.close_step(RetainedCloneGrant{maximum_items:0,..grant}).unwrap());assert_eq!(receipt,Default::default());assert_eq!(heap,(0,0));assert_eq!(cursor.next_demand(body).unwrap(),demand);let(receipt,heap)=observe(||cursor.close_step(grant).unwrap());assert!(receipt.fits(grant));stock.receive(receipt,heap);assert!(turn<99999,"original partial wire cancel stalled phase={phase} body={body} demand={demand:?}")}
 assert_eq!(stock.capacity,stock.released);assert_eq!(observe(||drop(cursor)).1,(0,0));
 }}
}
